INSERT INTO data_sources (source_id, source_name, methodology, coverage_note) VALUES
  (1, 'Meridian Panel Analytics', 'Opt-in consumer panel of 62,000 US households, weighted to census; cohort retention derived from panel sign-up and lapse dates.', 'Panel coverage of sub-scale services began July 2024; smaller services are absent before then because panel cells were below reporting threshold.'),
  (2, 'Cobalt Research Group', 'Normalisation of operator-reported subscriber and revenue disclosures, reconciled to a common calendar and definition of an active account.', 'Follows the reporting entity, so services whose parent reports them jointly arrive as a single combined revenue figure.'),
  (3, 'Streamscope Telemetry Co-op', 'Device-level playback telemetry from participating smart-TV and set-top manufacturers, projected to national viewing.', 'Covers the six largest services continuously; genre attribution follows the co-op taxonomy, which assigns each title exactly one genre.');
INSERT INTO content_genre (genre_id, genre_name, lifecycle_stage, description) VALUES
  (1, 'Prestige Drama', 'mature', 'Scripted long-form drama, awards-driven, high cost per hour.'),
  (2, 'Documentary', 'mature', 'Feature and episodic non-fiction, including true-crime strands.'),
  (3, 'Kids & Family', 'growing', 'Co-viewing catalogue for under-12s and family film libraries.'),
  (4, 'Anime', 'growing', 'Licensed and originally produced animation, largely simulcast.'),
  (5, 'Live Sports', 'growing', 'Live rights packages and same-day condensed replays.'),
  (6, 'Reality & Lifestyle', 'declining', 'Unscripted competition, property, cookery and lifestyle formats.');
