INSERT INTO market_events (event_id, event_date, event_type, service_id, headline, detail) VALUES
  (1, '2024-02-08', 'franchise_release', 1, 'Harrowgate season 4 arrives on Lumora+', 'The flagship prestige drama returned after an 18-month gap and drove the strongest gross-add month Lumora+ recorded in the window.'),
  (2, '2024-03-19', 'content_deal', 7, 'Kinoloft signs multi-year restoration output deal', 'Kinoloft acquired exclusive streaming rights to a restored arthouse library, adding roughly 140 titles across Prestige Drama and Documentary.'),
  (3, '2024-05-01', 'price_change', 1, 'Lumora+ raises standard tier from $12.99 to $14.49', 'First of two increases in the window. Cancellations rose sharply in June and stayed elevated through July before settling.'),
  (4, '2024-06-14', 'franchise_release', 2, 'Northgate Stream premieres The Saltway season 2', 'Northgate''s tentpole drama returned, lifting gross adds and briefly closing the subscriber gap with Lumora+.'),
  (5, '2024-07-02', 'content_deal', NULL, 'Studio output deals reshuffle across the market', 'Two mid-size studios moved their post-theatrical windows between services, affecting catalogue depth market-wide rather than any single service.'),
  (6, '2024-08-16', 'content_deal', 3, 'Kestrel wins exclusive US rights to the Anthem Cup', 'The rights package covering 2025-2029 is the inflection point in Kestrel''s growth; Live Sports share of its viewing climbs steadily from this month.'),
  (7, '2024-09-27', 'franchise_release', 8, 'Orikuma premieres Ashfall Chronicle season 3', 'Orikuma''s flagship anime drove its best gross-add month before the entrant arrived.'),
  (8, '2024-11-08', 'franchise_release', 5, 'Tidepool launches Nine Lantern Saga film', 'A theatrical-style anime feature released straight to Tidepool ahead of the Q4 season.'),
  (9, '2025-01-22', 'outage', 2, 'Northgate Stream suffers a 9-hour national outage', 'Playback failed for most of a Saturday evening. The incident drew press attention but left no lasting mark on the subscriber trend.'),
  (10, '2025-02-04', 'launch', 10, 'Cinder launches in the US', 'Ardent Global entered with a two-genre proposition — Anime and Kids & Family — priced at $13.49 with no advertising tier at launch.'),
  (11, '2025-03-14', 'franchise_release', 10, 'Cinder premieres Emberlight', 'The entrant''s first original anime series, released six weeks after launch to sustain the opening ramp.'),
  (12, '2025-04-11', 'content_deal', 9, 'Grovehouse secures exclusive festival documentary slate', 'A three-year first-look arrangement with two documentary festivals, reinforcing the service''s premium positioning.'),
  (13, '2025-05-30', 'franchise_release', 3, 'Kestrel begins Anthem Cup coverage', 'First live matches under the 2024 rights deal. Gross adds spiked and Live Sports overtook every other genre in Kestrel''s mix.'),
  (14, '2025-06-20', 'price_change', 5, 'Tidepool raises standard tier from $8.99 to $9.99', 'A modest increase, followed by a visible but short-lived cancellation spike in July and August 2025.'),
  (15, '2025-08-15', 'franchise_release', 1, 'Lumora+ releases Pebble & Bramble feature film', 'A Kids & Family tentpole timed to precede the autumn price increase.'),
  (16, '2025-09-01', 'price_change', 1, 'Lumora+ raises standard tier from $14.49 to $15.99', 'Second increase in 16 months. The cancellation spike in October and November 2025 was larger than after the 2024 rise, and retention did not recover.'),
  (17, '2025-10-17', 'franchise_release', 10, 'Cinder expands its Kids & Family slate', 'A block of originals aimed at co-viewing; Cinder passed Orikuma in subscribers during November 2025.'),
  (18, '2025-11-21', 'content_deal', 6, 'Harborlight renews its lifestyle format library', 'Harborlight extended its unscripted library licence even as the category declined market-wide.'),
  (19, '2026-01-09', 'outage', 5, 'Tidepool degraded service over a holiday weekend', 'Partial playback failures across three days in early January; no measurable effect on the month''s cancellations.'),
  (20, '2026-02-16', 'genre_exit', 4, 'Solstice TV exits Reality & Lifestyle', 'Solstice retired its unscripted slate, the genre it was most exposed to, after two years of falling viewing hours. It reports no Reality & Lifestyle engagement from February 2026 onward.'),
  (21, '2026-04-24', 'franchise_release', 3, 'Kestrel premieres Full Throttle Renovation season 6', 'An unscripted tentpole used to broaden Kestrel''s mix beyond live sports.'),
  (22, '2026-05-08', 'price_change', 9, 'Grovehouse raises standard tier from $17.99 to $18.99', 'The market''s highest price point moved higher. Cancellations rose in June 2026 but from the lowest base in the market.');
INSERT INTO known_data_gaps (gap_id, affected_table, affected_period, description) VALUES
  (1, 'genre_engagement', '2024-01 to 2024-06', 'Kinoloft, Orikuma and Grovehouse have no engagement rows before July 2024. Meridian Panel Analytics only began reporting sub-scale services once their panel cells cleared the reporting threshold. Genre totals before July 2024 therefore understate the market and must not be trended across that break.'),
  (2, 'retention_cohorts', '2024-01 to 2024-12', 'Solstice TV has no retention cohorts for any 2024 quarter. The service did not participate in the Meridian panel until January 2025, so its first measured cohort is 2025 Q1.'),
  (3, 'genre_engagement', '2026-02 to 2026-06', 'Solstice TV reports no Reality & Lifestyle engagement from February 2026 onward because it exited the genre (market_events event_id 20). The absence is a real withdrawal, not a measurement gap.'),
  (4, 'annual_revenue', '2024 to 2026', 'Tidepool and Harborlight share the parent Bellweather Media, which reports their subscription revenue as one combined figure. Both rows carry the SAME combined value with is_bundled = TRUE. Summing them double-counts, and the bundle cannot be split into standalone service revenue at any grain.'),
  (5, 'not modelled', 'entire window', 'Subscriber overlap between services is not modelled anywhere in this dataset. There is no household, account or panel-person table, so questions about how many people subscribe to two services simultaneously, or about cross-service duplication in market share, cannot be answered.');
